import re

def solve(env, goal):
    def find_nouns(text):
        return set(re.findall(r'\b[a-z]+\b', text.lower()))

    # Extract target object type and target receptacle type from goal.
    g = goal.lower()
    m = re.match(r'put a clean (\w+) (?:in|on) (?:a |the )?(\w+)', g)
    if not m:
        m = re.match(r'put a clean (\w+) (?:in|on) (\w+)', g)
    if m:
        obj_type, rec_type = m.group(1), m.group(2)
    else:
        # fallback: first noun after "clean", last noun
        words = re.findall(r'\b[a-z]+\b', g)
        obj_type = None
        rec_type = words[-1] if words else None
        for i, w in enumerate(words):
            if w == 'clean' and i + 1 < len(words):
                obj_type = words[i + 1]
                break

    def norm(s):
        return s.strip().lower()

    def parse_obs(obs):
        """Return (objects_here, receptacles_in_room)."""
        objs = []
        recs = []
        # objects visible on current receptacle
        mo = re.search(r'you see (.*?)\.', obs, re.I)
        if mo and 'nothing' not in mo.group(1).lower():
            objs = re.findall(r'(\w+(?:\s+\d+)?)', mo.group(1))
            objs = [norm(o) for o in objs]
        mr = re.findall(r'\b([a-z]+(?:\s+\d+)?)\b(?=[,.]|$)', obs)
        return objs, obs

    def list_receptacles(obs):
        """Extract all 'name N' tokens that look like receptacles."""
        return re.findall(r'\b([a-z]+(?:\s+\d+)?)\b', obs)

    def obj_matches(name, typ):
        return norm(name).split()[0] == typ

    def rec_matches(name, typ):
        return norm(name).split()[0] == typ

    history = []
    inventory = []

    def step(cmd):
        r = env.step(cmd)
        history.append((cmd, r))
        return r

    def current_obs():
        return env.observation

    def inv_objects():
        r = step('inventory')
        m = re.search(r'you are carrying (.*?)\.', r, re.I)
        if not m:
            return []
        part = m.group(1)
        if 'nothing' in part.lower():
            return []
        return [norm(o) for o in re.findall(r'(\w+(?:\s+\d+)?)', part)]

    # Track known object locations: obj -> (receptacle, opened?)
    known = {}
    opened = set()
    receptacles = []

    # Initial observation
    obs0 = current_obs()
    all_recs = re.findall(r'\b([a-z]+(?:\s+\d+)?)\b', obs0)
    # Keep only plausible receptacles (those with a number) - filter known object types
    for r in all_recs:
        if re.search(r'\d+', r):
            receptacles.append(norm(r))

    # Deduplicate preserving order
    seen = set()
    rec_list = []
    for r in receptacles:
        if r not in seen:
            seen.add(r)
            rec_list.append(r)
    receptacles = rec_list

    def goto(name):
        return step('go to ' + name)

    def open_place(name):
        if name in opened:
            return "already open"
        r = step('open ' + name)
        if 'nothing happens' not in r.lower():
            opened.add(name)
        return r

    # Find object of requested type by scanning receptacles.
    target_obj = None
    target_rec = None

    # First check if we already hold one
    held = inv_objects()
    for h in held:
        if obj_matches(h, obj_type):
            target_obj = h
            break

    if target_obj is None:
        # Search receptacles: visit each, open if needed, look at contents
        for rec in receptacles:
            if rec_matches(rec, obj_type):
                continue
            goto(rec)
            obs = current_obs()
            # If closed, open
            if re.search(r'it is closed|is closed', obs, re.I):
                open_place(rec)
                obs = current_obs()
            # Look for object
            m = re.search(r'you see (.*?)\.', obs, re.I)
            if m and 'nothing' not in m.group(1).lower():
                objs = [norm(o) for o in re.findall(r'(\w+(?:\s+\d+)?)', m.group(1))]
                for o in objs:
                    if obj_matches(o, obj_type):
                        target_obj = o
                        target_rec = rec
                        break
            if target_obj:
                break

    if target_obj is None:
        # try containers not yet visited: cabinets, drawers, fridge, microwave, safe
        extra = [r for r in receptacles if r not in seen]
        # Already handled; just return
        return

    # Ensure we have object in inventory
    held = inv_objects()
    if not any(obj_matches(h, obj_type) for h in held):
        # Go to receptacle and take
        if target_rec:
            goto(target_rec)
            obs = current_obs()
            if re.search(r'it is closed|is closed', obs, re.I):
                open_place(target_rec)
            step('take ' + target_obj + ' from ' + target_rec)

    # Clean it with sink basin
    sink = None
    for rec in receptacles:
        if rec_matches(rec, 'sinkbasin'):
            sink = rec
            break
    if sink:
        goto(sink)
        # clean
        held = inv_objects()
        for h in held:
            if obj_matches(h, obj_type):
                step('clean ' + h + ' with ' + sink)
                break

    # Find destination receptacle of requested type
    dest = None
    for rec in receptacles:
        if rec_matches(rec, rec_type):
            dest = rec
            break

    if dest is None:
        # Need to look around: maybe receptacle in another room - just use first matching
        # Scan observation for any name matching
        obs = current_obs()
        cand = re.findall(r'\b([a-z]+(?:\s+\d+)?)\b', obs)
        for c in cand:
            if rec_matches(c, rec_type):
                dest = norm(c)
                break

    if dest:
        goto(dest)
        obs = current_obs()
        if re.search(r'it is closed|is closed', obs, re.I):
            open_place(dest)
        held = inv_objects()
        for h in held:
            if obj_matches(h, obj_type):
                step('move ' + h + ' to ' + dest)
                break

    return
